sql.where:
e.is_deleted = 0
AND e.equipment_id IS NOT NULL
AND e.equipment_id > 0

    AND e.equipment_id = #{q.equipmentId}


    AND eq.equipment_type = #{q.equipmentType}


    AND  = #{q.status}


    AND (
        wo.work_order_code LIKE CONCAT('%', #{q.keyword}, '%')
        OR wo.batch_number LIKE CONCAT('%', #{q.keyword}, '%')
        OR wo.preparation_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR pt.process_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR eq.equipment_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR eq.fixed_asset_code LIKE CONCAT('%', #{q.keyword}, '%')
    )



    AND e.start_time IS NOT NULL
    AND e.end_time IS NOT NULL
    AND e.end_time > #{q.startTime}


    AND e.start_time IS NOT NULL
    AND e.end_time IS NOT NULL
    AND e.start_time < #{q.endTime}

mapper.select:
SELECT



ORDER BY eq.equipment_name ASC, e.start_time ASC, e.id ASC

    LIMIT #{limit}
